CREATE TABLE IF NOT EXISTS players (id TEXT PRIMARY KEY, name TEXT NOT NULL, platform TEXT NOT NULL, price INTEGER NOT NULL DEFAULT 10000, rp INTEGER, season TEXT, updated TEXT, created TEXT);
CREATE TABLE IF NOT EXISTS ticks (id INTEGER PRIMARY KEY AUTOINCREMENT, player TEXT NOT NULL, match_id TEXT NOT NULL, created TEXT NOT NULL, price INTEGER NOT NULL, change_pct REAL NOT NULL, kills INTEGER, damage REAL, rank INTEGER, rp_delta INTEGER, reason TEXT, UNIQUE(player,match_id));
CREATE TABLE IF NOT EXISTS settings (k TEXT PRIMARY KEY,v TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS processed (player TEXT NOT NULL, match_id TEXT NOT NULL, PRIMARY KEY(player,match_id));
CREATE TABLE IF NOT EXISTS snapshots (player TEXT NOT NULL, created TEXT NOT NULL, season TEXT, rp INTEGER);
CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY,v TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_ticks_player ON ticks(player,id);
